package org.dromara.ai.workspace;

import lombok.RequiredArgsConstructor;
import org.dromara.common.json.utils.JsonUtils;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.multipart.MultipartFile;
import java.util.*;
import java.util.regex.*;

@Service @RequiredArgsConstructor
public class WorkspaceKnowledge {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final WorkspaceKnowledgeAccess access;private final WorkspaceFileStore files;private final WorkspaceKnowledgeDocumentExtractor extractor;private final WorkspaceConversations conversations;private final WorkspaceEvents events;
 public Map<String,Object> upload(UUID base,UUID document,Integer expected,UUID key,long user,MultipartFile file){
  access.base(base,user,AiResourceGuard.Action.EDIT);String name=WorkspaceFileStore.filename(file);byte[] bytes=WorkspaceFileStore.upload(file,10*1024*1024);var descriptor=extractor.describe(name,bytes);
  return tx.execute(status->{jdbc.queryForObject("SELECT user_id FROM sys_user WHERE user_id=? FOR UPDATE",Long.class,user);String digest=WorkspaceTools.hash(base+":"+document+":"+expected+":"+name+":"+WorkspaceFileStore.hash(bytes));var old=jdbc.queryForList("SELECT input_hash,result::text FROM ai_command WHERE actor_user_id=? AND operation='knowledge.upload' AND idempotency_key=?",user,key);if(!old.isEmpty()){if(!digest.equals(old.getFirst().get("input_hash")))throw new WorkspaceDenied(409,"IdempotencyConflict");return JsonUtils.parseMap(old.getFirst().get("result").toString());}access.base(base,user,AiResourceGuard.Action.EDIT);
   UUID id=document==null?UUID.randomUUID():document;int version=1;if(document==null){if(jdbc.queryForObject("SELECT count(*) FROM ai_knowledge_document WHERE base_id=? AND deleted_at IS NULL",Integer.class,base)>=50)throw new WorkspaceDenied(409,"KnowledgeDocumentLimit");jdbc.update("INSERT INTO ai_knowledge_document(id,base_id,title,created_by) VALUES(?,?,?,?)",id,base,name,user);}else{jdbc.queryForList("SELECT id FROM ai_knowledge_document WHERE id=? FOR UPDATE",id);var doc=access.document(id,user,AiResourceGuard.Action.EDIT);if(!doc.get("base_id").equals(base)||expected==null||((Number)doc.get("latest_version")).intValue()!=expected)throw new WorkspaceDenied(409,"VersionConflict");version=expected+1;jdbc.update("UPDATE ai_knowledge_document SET latest_version=?,title=?,updated_at=NOW() WHERE id=?",version,name,id);}
   UUID fileId=files.save(user,"KNOWLEDGE",base,null,name,descriptor.mediaType(),bytes),job=UUID.randomUUID();jdbc.update("INSERT INTO ai_knowledge_document_version(document_id,version,file_id,text_content,content_hash,source_media_type,extraction_method) VALUES(?,?,?,?,?,?,'PENDING')",id,version,fileId,"",WorkspaceTools.hash(""),descriptor.mediaType());jdbc.update("INSERT INTO ai_knowledge_job(id,document_id,version,requested_by) VALUES(?,?,?,?)",job,id,version,user);
   Map<String,Object> result=new LinkedHashMap<>();result.put("id",id.toString());result.put("version",version);result.put("fileId",fileId.toString());result.put("jobId",job.toString());result.put("status","QUEUED");result.put("mediaType",descriptor.mediaType());jdbc.update("INSERT INTO ai_command(actor_user_id,operation,idempotency_key,input_hash,result) VALUES(?,'knowledge.upload',?,?,?::jsonb)",user,key,digest,JsonUtils.toJsonString(result));audit(user,"knowledge.document.uploaded",base,Map.of("documentId",id.toString(),"version",version,"mediaType",descriptor.mediaType()));return result;
  });
 }
 public List<Map<String,Object>> documents(UUID base,long user,int page){access.base(base,user,AiResourceGuard.Action.VIEW);boolean edit;try{access.base(base,user,AiResourceGuard.Action.EDIT);edit=true;}catch(WorkspaceDenied e){edit=false;}var rows=jdbc.queryForList("SELECT d.id::text,f.filename AS title,d.latest_version,d.indexed_version,v.version,v.status,v.file_id::text,v.source_media_type AS media_type,v.extraction_method,v.extraction_metadata::text,d.updated_at::text FROM ai_knowledge_document d JOIN ai_knowledge_document_version v ON v.document_id=d.id AND v.version=CASE WHEN ? THEN d.latest_version ELSE CASE WHEN ? THEN (SELECT version FROM ai_public_document p WHERE p.resource_id=d.base_id AND p.document_id=d.id) ELSE d.indexed_version END END JOIN ai_file f ON f.id=v.file_id WHERE d.base_id=? AND d.deleted_at IS NULL ORDER BY d.updated_at DESC LIMIT 30 OFFSET ?",edit,access.publicOnly(base,user,AiResourceGuard.Action.VIEW),base,(Math.max(1,Math.min(page,1000))-1)*30);for(var row:rows)row.put("extraction_metadata",JsonUtils.parseMap(row.get("extraction_metadata").toString()));return rows;}
 public void remove(UUID document,long user){tx.executeWithoutResult(status->{jdbc.queryForList("SELECT id FROM ai_knowledge_document WHERE id=? FOR UPDATE",document);var d=access.document(document,user,AiResourceGuard.Action.DELETE);jdbc.update("UPDATE ai_knowledge_document SET deleted_at=NOW(),auth_version=auth_version+1 WHERE id=?",document);jdbc.update("UPDATE ai_file SET deleted_at=NOW(),auth_version=auth_version+1 WHERE id IN(SELECT file_id FROM ai_knowledge_document_version WHERE document_id=?)",document);jdbc.update("UPDATE ai_knowledge_job SET status='CANCELLED',finished_at=NOW() WHERE document_id=? AND status IN('QUEUED','RUNNING')",document);audit(user,"knowledge.document.deleted",(UUID)d.get("base_id"),Map.of("documentId",document.toString()));});conversations.revokeDocument(document);}
 public Map<String,Object> reindex(UUID document,long user){return tx.execute(status->{jdbc.queryForList("SELECT id FROM ai_knowledge_document WHERE id=? FOR UPDATE",document);var d=access.document(document,user,AiResourceGuard.Action.EDIT);var active=jdbc.queryForList("SELECT id FROM ai_knowledge_job WHERE document_id=? AND version=? AND status IN('QUEUED','RUNNING')",document,d.get("latest_version"));if(!active.isEmpty())return Map.of("jobId",active.getFirst().get("id").toString(),"reused",true);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO ai_knowledge_job(id,document_id,version,requested_by) VALUES(?,?,?,?)",id,document,d.get("latest_version"),user);jdbc.update("UPDATE ai_knowledge_document_version SET status=CASE WHEN status='READY' THEN status ELSE 'QUEUED' END WHERE document_id=? AND version=?",document,d.get("latest_version"));return Map.of("jobId",id.toString(),"reused",false);});}
 public List<Map<String,Object>> jobs(UUID base,long user){access.base(base,user,AiResourceGuard.Action.VIEW);if(access.publicOnly(base,user,AiResourceGuard.Action.VIEW))return List.of();return jdbc.queryForList("SELECT j.id::text AS job_id,j.document_id::text,j.version,j.status,j.error_code,j.created_at::text,j.finished_at::text FROM ai_knowledge_job j JOIN ai_knowledge_document d ON d.id=j.document_id WHERE d.base_id=? AND d.deleted_at IS NULL ORDER BY j.created_at DESC LIMIT 30",base);}
 static List<String> queryTerms(String normalized){
  List<String> segments=new ArrayList<>(),grams=new ArrayList<>();Matcher words=Pattern.compile("[\\p{L}\\p{N}]+").matcher(normalized.toLowerCase(Locale.ROOT));
  while(words.find()&&segments.size()<16){String segment=words.group();int length=segment.codePointCount(0,segment.length());if(length<=48)segments.add(segment);Matcher han=Pattern.compile("\\p{IsHan}+").matcher(segment);while(han.find()){int[] points=han.group().codePoints().toArray();if(points.length<4)continue;for(int i=0;i<points.length-1;i++)grams.add(new String(points,i,2));}}
  LinkedHashSet<String> terms=new LinkedHashSet<>(segments);int available=32-terms.size();if(available>0&&!grams.isEmpty()){if(grams.size()<=available)terms.addAll(grams);else if(available==1)terms.add(grams.get(grams.size()/2));else for(int i=0;i<available;i++)terms.add(grams.get((int)Math.round((double)i*(grams.size()-1)/(available-1))));}
  return List.copyOf(terms);
 }
 private static String likePattern(String value){return "%"+value.replace("!","!!").replace("%","!%").replace("_","!_")+"%";}
 private List<Map<String,Object>> matches(UUID base,UUID run,String query,boolean publicOnly){
  if(query==null||query.isBlank()||query.length()>200)throw new WorkspaceDenied(400,"InvalidKnowledgeQuery");String normalized=query.trim();List<String> terms=queryTerms(normalized);if(terms.isEmpty())throw new WorkspaceDenied(400,"InvalidKnowledgeQuery");
  String values=String.join(",",Collections.nCopies(terms.size(),"(?::text)"));List<Object> args=new ArrayList<>();for(String term:terms)args.add(likePattern(term));
  String source;if(run!=null){source="JOIN ai_run_document p ON p.document_id=i.document_id AND p.version=i.version WHERE p.run_id=?";args.add(run);}else{source="WHERE d.base_id=? AND i.version="+(publicOnly?"(SELECT version FROM ai_public_document p WHERE p.resource_id=d.base_id AND p.document_id=d.id)":"d.indexed_version");args.add(base);}args.add(normalized);args.add(normalized);args.add(normalized);args.add(normalized);args.add(normalized);
  String sql="WITH query_terms(pattern) AS (VALUES "+values+") SELECT i.document_id::text,i.version,i.chunk_index,i.line_start,i.line_end,i.location_type,i.location_label,i.content,f.filename AS title,v.file_id::text,f.sha256,v.source_media_type,"+
   "COALESCE((SELECT SUM((CASE WHEN f.filename ILIKE q.pattern ESCAPE '!' OR d.title ILIKE q.pattern ESCAPE '!' THEN 4 ELSE 0 END)+(CASE WHEN COALESCE(i.location_label,'') ILIKE q.pattern ESCAPE '!' THEN 2 ELSE 0 END)+(CASE WHEN i.content ILIKE q.pattern ESCAPE '!' THEN 1 ELSE 0 END)) FROM query_terms q),0) AS lexical_score "+
   "FROM ai_knowledge_index i JOIN ai_knowledge_document d ON d.id=i.document_id JOIN ai_knowledge_document_version v ON v.document_id=i.document_id AND v.version=i.version JOIN ai_file f ON f.id=v.file_id "+source+
   " AND d.deleted_at IS NULL AND v.status='READY' AND (i.search_vector @@ websearch_to_tsquery('simple',?) OR i.content % ? OR EXISTS(SELECT 1 FROM query_terms q WHERE i.content ILIKE q.pattern ESCAPE '!' OR f.filename ILIKE q.pattern ESCAPE '!' OR d.title ILIKE q.pattern ESCAPE '!' OR COALESCE(i.location_label,'') ILIKE q.pattern ESCAPE '!')) "+
   "ORDER BY lexical_score DESC,(CASE WHEN i.search_vector @@ websearch_to_tsquery('simple',?) THEN ts_rank_cd(i.search_vector,websearch_to_tsquery('simple',?)) ELSE 0 END)+similarity(i.content,?) DESC,i.document_id,i.chunk_index LIMIT 8";
  return jdbc.queryForList(sql,args.toArray());
 }
 public Map<String,Object> search(UUID base,long user,String query){access.base(base,user,AiResourceGuard.Action.USE);var rows=matches(base,null,query,access.publicOnly(base,user,AiResourceGuard.Action.USE));access.base(base,user,AiResourceGuard.Action.USE);UUID searchId=UUID.randomUUID();List<Map<String,Object>> citations=new ArrayList<>();List<String> trace=new ArrayList<>();for(int i=0;i<rows.size();i++){var c=citationDto(rows.get(i),"S"+(i+1));citations.add(c);trace.add(c.get("documentId")+":"+c.get("version")+":"+c.get("chunkIndex"));}audit(user,"knowledge.search",base,Map.of("searchId",searchId.toString(),"queryHash",WorkspaceTools.hash(query.trim()),"resultCount",citations.size(),"citations",trace));return Map.of("searchId",searchId.toString(),"retrievalMode","POSTGRES_LEXICAL","citations",citations);}
 public Map<String,Object> retrieve(String grant,String query){return tx.execute(status->{var run=conversations.checkGrant(grant,true);UUID id=(UUID)run.get("id");jdbc.queryForObject("SELECT id FROM ai_run WHERE id=? FOR UPDATE",UUID.class,id);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_run_document WHERE run_id=?)",Boolean.class,id)))throw new WorkspaceDenied(403,"KnowledgeNotSelected");var results=matches(null,id,query,false);List<Map<String,Object>> citations=new ArrayList<>();for(var row:results){UUID doc=UUID.fromString(row.get("document_id").toString());int version=((Number)row.get("version")).intValue(),chunk=((Number)row.get("chunk_index")).intValue();var previous=jdbc.queryForList("SELECT id,reference FROM ai_knowledge_citation WHERE run_id=? AND document_id=? AND version=? AND chunk_index=?",id,doc,version,chunk);UUID citation=previous.isEmpty()?UUID.randomUUID():(UUID)previous.getFirst().get("id");String reference=previous.isEmpty()?"K"+(jdbc.queryForObject("SELECT count(*) FROM ai_knowledge_citation WHERE run_id=?",Integer.class,id)+1):previous.getFirst().get("reference").toString();if(previous.isEmpty())jdbc.update("INSERT INTO ai_knowledge_citation(id,run_id,document_id,version,chunk_index,reference) VALUES(?,?,?,?,?,?)",citation,id,doc,version,chunk,reference);var value=citationDto(row,reference);value.put("id",citation.toString());citations.add(value);}conversations.checkGrant(grant,true);events.append((UUID)run.get("session_id"),id,UUID.randomUUID(),"knowledge.retrieved",Map.of("citations",citations));audit(((Number)run.get("owner_user_id")).longValue(),"knowledge.retrieved",null,Map.of("runId",id.toString(),"resultCount",citations.size()));return Map.of("citations",citations,"retrievalMode","POSTGRES_LEXICAL","instruction","仅依据返回原文回答，用 [K1] 等引用编号；无匹配时明确说明未找到，不猜测。");});}
 private Map<String,Object> citationDto(Map<String,Object> row,String reference){String document=row.get("document_id").toString(),file=row.get("file_id").toString();int version=((Number)row.get("version")).intValue();Map<String,Object> value=new LinkedHashMap<>();value.put("reference",reference);value.put("documentId",document);value.put("version",version);value.put("chunkIndex",row.get("chunk_index"));value.put("locationType",row.get("location_type"));value.put("locationLabel",row.get("location_label"));value.put("lineStart",row.get("line_start"));value.put("lineEnd",row.get("line_end"));value.put("content",row.get("content"));value.put("title",row.get("title"));value.put("fileId",file);value.put("sha256",row.get("sha256"));value.put("mediaType",row.get("source_media_type"));value.put("sourceUrl","/api/ai/knowledge/documents/"+document+"/versions/"+version);value.put("downloadUrl","/api/ai/files/"+file+"/download");return value;}
 public Map<String,Object> citation(UUID id,WorkspacePrincipal.Actor actor){var rows=jdbc.queryForList("SELECT c.*,r.session_id FROM ai_knowledge_citation c JOIN ai_run r ON r.id=c.run_id WHERE c.id=? AND r.owner_user_id=?",id,actor.userId());if(rows.size()!=1)throw new WorkspaceDenied(404,"CitationNotFound");var c=rows.getFirst();conversations.authorizeSession((UUID)c.get("session_id"),actor);return preview((UUID)c.get("document_id"),((Number)c.get("version")).intValue(),actor.userId());}
 public Map<String,Object> preview(UUID document,int version,long user){var v=access.version(document,version,user,AiResourceGuard.Action.VIEW);var f=access.file((UUID)v.get("file_id"),user);audit(user,"knowledge.document.previewed",(UUID)f.get("resource_id"),Map.of("documentId",document.toString(),"version",version));Map<String,Object> result=new LinkedHashMap<>();result.put("documentId",document.toString());result.put("version",version);result.put("filename",f.get("filename"));result.put("content",v.get("text_content"));result.put("fileId",f.get("id").toString());result.put("sha256",f.get("sha256"));result.put("mediaType",v.get("source_media_type"));result.put("extractionMethod",v.get("extraction_method"));result.put("extractionMetadata",JsonUtils.parseMap(v.get("extraction_metadata").toString()));result.put("status",v.get("status"));return result;}
 private void audit(long user,String action,UUID resource,Map<String,Object> metadata){jdbc.update("INSERT INTO ai_security_event(id,actor_user_id,action,resource_id,metadata) VALUES(?,?,?,?,?::jsonb)",UUID.randomUUID(),user,action,resource,JsonUtils.toJsonString(metadata));}
}
